'use client'
import { Fragment, type ElementType, type MouseEvent } from 'react'
import { ChevronRight } from 'lucide-react'
import { cn } from '@/react/lib/cn'

// shadcn's breadcrumb in the brand: where you are, in DM Sans 14px. Each step back is a muted link that turns White
// under the pointer (160ms), a small chevron between them, and the page itself in White, the only step that truncates.
// `as` renders a router link component for the steps back (it gets `href` and `to`); `onNavigate` hears a click.
export interface Crumb {
  label: string
  href?: string
}
export interface BreadcrumbProps {
  /** The steps, the page last. */
  items: Crumb[]
  /** The trail's name for assistive tech. */
  label?: string
  /** A router link component for the steps back. */
  as?: ElementType
  onNavigate?: (crumb: Crumb, event: MouseEvent) => void
  className?: string
}

export function Breadcrumb({ items, label = 'Breadcrumb', as: Link = 'a', onNavigate, className }: BreadcrumbProps) {
  return (
    <nav data-ds="breadcrumb" className={cn('flex min-w-0 items-center gap-1.5 overflow-hidden type-ui', className)} aria-label={label}>
      {items.map((crumb, i) => (
        <Fragment key={i}>
          {i > 0 && <ChevronRight size={14} strokeWidth={1.5} className="shrink-0 text-fg-faint rtl:-scale-x-100" aria-hidden="true" />}
          {i < items.length - 1
            ? <Link href={crumb.href ?? '#'} to={Link === 'a' ? undefined : crumb.href} className="shrink-0 rounded-ds-sm text-fg-muted transition-[color] duration-160 ease-standard hover:text-fg" onClick={(event: MouseEvent) => onNavigate?.(crumb, event)}>{crumb.label}</Link>
            : <span className="min-w-0 truncate text-fg" aria-current="page">{crumb.label}</span>}
        </Fragment>
      ))}
    </nav>
  )
}

export default Breadcrumb

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

